-- CineAstra | complemento de catálogo de QA com 1.000 filmes.
-- Executar após o instalador e 01_inserts.sql, sem --force e com FKs habilitadas.
-- Catálogo Cinemeta (Stremio), IDs TMDB e mídia MetaHub/YouTube.
-- Fonte: https://github.com/Stremio/stremio-official-addons
-- Títulos e sinopses no idioma fornecido pela fonte. Todos os trailers são links externos.
-- Classificação conservadora 18 até revisão brasileira, pois a fonte não a fornece.
-- O pacote não distribui arquivos de filmes nem habilita compra ou aluguel.
SET NAMES utf8mb4;
DROP TEMPORARY TABLE IF EXISTS seed_catalogo_1000;
CREATE TEMPORARY TABLE seed_catalogo_1000 (
  tmdb_id INT UNSIGNED PRIMARY KEY, titulo VARCHAR(200) NOT NULL, descricao TEXT,
  duracao INT NOT NULL, lancamento DATE NOT NULL, diretor VARCHAR(150),
  poster VARCHAR(255) NOT NULL, banner VARCHAR(2048) NOT NULL, trailer VARCHAR(255) NOT NULL, generos JSON NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;











START TRANSACTION;

-- Eliminar do lote filmes já cadastrados por título e data ou pelo trailer associado.
DELETE seed FROM seed_catalogo_1000 seed
JOIN filmes f ON (f.titulo COLLATE utf8mb4_unicode_ci = seed.titulo AND f.data_lancamento = seed.lancamento)
  OR (f.trailer = seed.trailer AND f.data_lancamento = seed.lancamento);

SELECT titulo, descricao, duracao, '18', lancamento, diretor, poster, trailer, TRUE, TRUE, 'ATIVO'
FROM seed_catalogo_1000 ORDER BY tmdb_id;

SELECT f.id_filme, 'CAPA', seed.poster, CONCAT('Cartaz de ', seed.titulo), 0, TRUE
FROM seed_catalogo_1000 seed
JOIN filmes f ON f.titulo COLLATE utf8mb4_unicode_ci = seed.titulo AND f.data_lancamento = seed.lancamento;

SELECT f.id_filme, 'BANNER', seed.banner, CONCAT('Banner de ', seed.titulo), 0, TRUE
FROM seed_catalogo_1000 seed
JOIN filmes f ON f.titulo COLLATE utf8mb4_unicode_ci = seed.titulo AND f.data_lancamento = seed.lancamento;

SELECT DISTINCT j.nome COLLATE utf8mb4_unicode_ci, 'ATIVO'
FROM seed_catalogo_1000 seed
CROSS JOIN JSON_TABLE(seed.generos, '$[*]' COLUMNS (nome VARCHAR(100) PATH '$')) j
WHERE NOT EXISTS (SELECT 1 FROM generos g WHERE g.nome COLLATE utf8mb4_unicode_ci = j.nome COLLATE utf8mb4_unicode_ci);

SELECT DISTINCT f.id_filme, g.id_genero
FROM seed_catalogo_1000 seed
JOIN filmes f ON f.titulo COLLATE utf8mb4_unicode_ci = seed.titulo AND f.data_lancamento = seed.lancamento
CROSS JOIN JSON_TABLE(seed.generos, '$[*]' COLUMNS (nome VARCHAR(100) PATH '$')) j
JOIN generos g ON g.nome COLLATE utf8mb4_unicode_ci = j.nome COLLATE utf8mb4_unicode_ci;

COMMIT;
SELECT COUNT(*) AS filmes_inseridos FROM seed_catalogo_1000;
DROP TEMPORARY TABLE seed_catalogo_1000;
